exec(open("batches/hiv_common.py").read())
# HIV 2022 part 4, pp.199-207 (Chapter 9: ART for children and adolescents - preparation, adherence plan, timing, AHD, STOP AIDS).
# From the page images (Table 9.1 first column read from the image; its text layer is overprinted), wording checked against the text layer.
C9 = "Chapter 9: ART for Children and Adolescents"
B_ = lambda *xs: "<br/>".join("• " + x for x in xs)
AHD = "Superseded in part by the 2024 Amendment (Chapter 6): CrAg screening and TB LAM at CD4 ≤200 cells/µL; VISITECT CD4 for AHD screening where available."
ITEMS = [
 B("box-9.1-same-day-initiation", 200, C9 + " > 9.1 Preparations of Children and Adolescents for ART > Social Considerations for ART Initiation and Chronic Care", "Same-day ART initiation for children and adolescents (key message)", [],
   "Key message: Children and adolescents should be initiated on ART as soon as possible, preferably on the same day of testing positive for HIV diagnosis while adherence-counselling process is ongoing."),
 B("box-9-contacts", 199, C9, "Important contacts (children and adolescents)", ["0544"],
   "DBS Hotline: 7687-9925\nBaylor HIV/TB Hotline: 7848-5571\nSNAP 3rd Line Committee e-mail: snapthirdline@mohcoag.org"),
 D("fig-9.1-adherence-plan", 203, C9 + " > 9.1 Preparations of Children and Adolescents for ART > Figure 9.1", "Figure 9.1 Steps to use when developing an adherence plan", [],
   "1. Adopt a 'no-blame' approach to facilitate open and honest discussion.\n"
   "2. Actively involve the client/parent (caregiver) in the decision-making of their child's or their own care and treatment.\n"
   "3. The benefits of ART and long-term optimal adherence should be emphasized: improved quality of life (improved/normal growth & development, reduced illness); sustained undetectable viral load; decreased risk of HIV transmission (particularly for adolescents; U=U (Undetectable = Untransmittable)); decreased chance of HIV developing resistance to ARVs.\n"
   "4. Children, adolescents and caregivers' knowledge, understanding and concerns about medicines and the benefits they perceive should be reviewed regularly.\n"
   "5. Interventions to support adherence should be individualized to address specific barriers: identify and address any concerns about the need for and administering ART; identify and address practical barriers to adherence (limitations in capacity and resources): identifying an informed primary and secondary caregiver to be involved in providing care, fitting ART into the child's (or caregiver's) daily schedule(s), use of calendars or other visual aids to illustrate dosing, directly observed therapy, use of pillboxes, reminders, alarms and timers; peer support groups (teen clubs) for children, adolescents, and caregivers; age-appropriate and family disclosure; clients' experience of taking ART and their needs for adherence support may change over time.\n"
   "6. Provide an outlook of the client's care in terms of availability of diverse care models to choose from: strategies in place for client-centred care models at least 1 year after starting ART when the virus is fully under control; include information on DSD models: MMD, Baby Club, Teen Club, etc."),
 T("tbl-9.1-art-timing-children", 204, C9 + " > 9.3 When to Start ART for Children and Adolescents > Table 9.1", "Table 9.1 Timing of ART initiation (after HIV verification/confirmation and clinical assessment)", ["0553", "0554"],
   [r("Clinical status", "Timing of ART initiation")],
   [r("CALHIV with HIV with no signs and symptoms of TB", "Rapid ART initiation on the same day should be offered to all people living with HIV (Test and Start)"),
    r("CALHIV with suspected TB", "Offer rapid ART initiation while rapidly investigating for TB, with close follow-up within 7 days to initiate TB treatment if TB is confirmed*<br/>*This is except for cases where the history and clinical examination indicate signs and symptoms of TB meningitis"),
    r("CALHIV has already been diagnosed with TB but not receiving ART or treatment for TB", "Initiate TB treatment first<br/>Initiate ART as soon as possible within 2 weeks of TB treatment"),
    r("CALHIV with being treated for HIV-associated TB (including multi-drug-resistant TB (MDR))", "Initiate TB treatment first<br/>Initiate ART within 2 weeks of initiating TB treatment, regardless of CD4 cell count"),
    r("CALHIV being treated for HIV-associated TB meningitis (either clinically or with a confirmed laboratory test)", "Initiate TB treatment first<br/>Delay ART initiation by at least 4 weeks (and initiated within eight weeks) after treatment for TB meningitis begins"),
    r("CALHIV with cryptococcal meningitis", "Immediate ART initiation is contraindicated because of the increased mortality presumed to be caused by immune reconstitution inflammatory syndrome in the central nervous system<br/>ART should be initiated between 4–6 weeks after beginning antifungal treatment"),
    r("CALHIV who are hospitalized or severely ill", "Acute management of the illness is the priority.<br/>ART should be initiated within 14 days, after medical stabilization of the coexisting illness.")],
   context_before="All HIV-infected children and adolescents are eligible to start ART regardless of CD4 count or WHO clinical stage. It is imperative to confirm all presumptively diagnosed children with DNA PCR. Assess the client's and caregiver's readiness and address barriers to ART initiation. Initiate ART as soon after diagnosis as possible (preferably 0-14 days).",
   footnotes=["ART should be deferred in a seriously ill child presenting with any of the following danger signs: temperature ≥39°C; lethargy or unconsciousness; repeated vomiting; unable to drink or breastfeed; convulsions; tachycardia and/or tachypnoea. Children and adolescents with these danger signs require acute medical management +/- referral for admission and should not be initiated on ART until stable."],
   source_flags=["Cryptococcal meningitis: ART 4-6 weeks after antifungal treatment here, '6-8 weeks' in the STOP AIDS box (p.206), 6 weeks in Chapter 6 and 2-6 weeks in Chapter 7 (Table 7.1 notes)."]),
 T("tbl-9.2-ahd-definitions-children", 205, C9 + " > 9.4 Advanced HIV Disease (AHD) in children and adolescents > Table 9.2", "Table 9.2 Definitions of Advanced Immunodeficiency and High-Risk Groups", ["0557"],
   [r("Group", "Advanced Immunodeficiency (Severe Immunodeficiency)", "High-Risk Group (Very Severe Immunodeficiency)")],
   [r("Adolescents", B_("CD4 count ≤200 cells/mm³ or", "WHO clinical stage 3 or 4"), B_("CD4 count ≤100 cells/mm³")),
    r("Children", "Children ≥5 years:<br/>" + B_("CD4 count ≤200 cells/mm3 or CD4 less than 25%", "WHO clinical stage 3 or 4") + "<br/>Children < 5 years:<br/>" + B_("Manage as clients with advanced immunodeficiency (Advanced disease)"),
      "Children ≥5 years:<br/>" + B_("CD4 count ≤100 cells/mm3 or less than 25%") + "<br/>Children <5 years:<br/>" + B_("CD4 count ≤100 cells/mm³ or <25%."))],
   context_before="All children with HIV who are younger than 5 years and have not been on treatment for at least 12 months are considered a high-risk group and managed as having advanced immunodeficiency. Children above 2 years who have been on ART, and are stable, for at least one year may not be considered as having AHD. Prioritize assessment (clinical and social) and rapid ART initiation in children and adolescents with advanced disease as soon as possible (within 7 days) from the day of HIV diagnosis.",
   footnotes=["CD4 cell count is the best indicator of disease stage and immediate risk of death. Children and adolescents at risk of advanced HIV disease include those presenting to care for the first time following an HIV diagnosis, identified with treatment failure and consequent decline in CD4 count, and previously initiated on ART and re-engaging after a period of interruption."],
   source_flags=["The high-risk (very severe) threshold for children uses the same 'less than 25%' CD4 percentage as the advanced threshold, so the two categories cannot be told apart by CD4%.", "'Children above 2 years ... on ART for at least one year may not be considered as having AHD' conflicts with 'all children younger than 5 years' in the same paragraph and in Table 9.2.", AHD]),
 B("tbl-9.3-stop-aids", 206, C9 + " > 9.4 > Package of care for children and adolescents with Advanced HIV Disease > Table 9.3", "Table 9.3 Stop AIDS strategy (Screen, Treat, Optimize, Prevent) and Figure 9.2", ["0559", "0561", "0563", "0565", "0566"],
   "Figure 9.2 Elements of STOP strategy: Screen, Treat, Optimize and Prevent AIDS (STOP AIDS) - the package of care for children and adolescents with advanced HIV disease.\n"
   "Identify and treat opportunistic infections BEFORE initiating ART. Client with active TB (other than TB meningitis): initiate ART as soon as possible (within 2 weeks) following initiation of anti-TB treatment. Client with cryptococcal infection or meningitis: ART initiation should be delayed for 6-8 weeks after starting treatment for meningitis.\n"
   "SCREEN\nScreen for TB:\n- Use a clinical algorithm (see Figure 6.1) followed by an X-ray when indicated and if available\n- Use recommended diagnostic tests to confirm TB as applicable:\n   1. Rapid molecular diagnostic (Xpert® MTB/RIF or Ultra) on (induced) sputum, stool, gastric aspirate or nasopharyngeal aspirate or other extra-pulmonary samples if relevant\n   2. Lateral flow urine lipoarabinomannan (LF-LAM) assay\n"
   "Indications for LF-LAM use in the diagnosis of active TB among CALHIV:\n- Inpatient settings: with signs and symptoms of TB (pulmonary and/or extrapulmonary); with advanced HIV disease or who are seriously ill regardless of signs and symptoms of TB and with a CD4 count <200 cells/mm³\n"
   "- Outpatient settings: with signs and symptoms of TB (pulmonary and/or extrapulmonary); seriously ill regardless of signs and symptoms of TB and with a CD4 cell count <100 cells/mm³\n"
   "LF-LAM should not be used to assist in diagnosing active TB among children and adolescents in the following situations: A. without assessing TB symptoms; B. without TB symptoms and unknown CD4 cell count or without TB symptoms and the CD4 cell count ≥200 cells/mm³; C. without TB symptoms and with a CD4 cell count of 100–200 cells/mm³\n"
   "Screen for cryptococcal infection among adolescents: serum or plasma or blood cryptococcal antigen screening followed by lumbar puncture if positive or symptomatic\n"
   "Screen for malnutrition: weight-for-height (Wt/Ht); height-for-age (Ht/Age); mid-upper arm circumference (MUAC) among children 2–5 years old; weight for age (Wt/Age)\n"
   "TREAT\nTreat opportunistic infections: this includes TB, severe pneumonia, severe bacterial infections, gastroenteritis, cryptococcal meningitis and severe acute malnutrition\n"
   "OPTIMIZE\n- Rapid antiretroviral therapy initiation with optimal regimens (within 7 days)\n- Antiretroviral therapy counselling\n- Intensified adherence support interventions\n"
   "PREVENT\n- Bacterial infections and Pneumocystis pneumonia: co-trimoxazole prophylaxis\n- TB: TB preventive treatment\n- Cryptococcal meningitis among adolescents: fluconazole pre-emptive therapy\n- Vaccination (see National vaccination schedule Annex 11.33): pneumococcal vaccine, HPV (adolescents), measles, BCG",
   pages=[206, 207], flags=[AHD]),
]
